/**
 * 改造自 shadcn 原装 base-lyra message（https://ui.shadcn.com/r/styles/base-lyra/message.json，MIT）。
 * 按 #16 改造：MessageAvatar 组合原装 Avatar（Q9）；-translate-y-8 写死，不升格为令牌（Q6）。
 * 动效由 `motion` 属性选预设（ADR 0021）：`Message` 渲染 `data-motion`，挂载时入场（基础层的 `@starting-style`），
 * 缺省 `slide-up`。里面的 Bubble 用缺省 motion 时不再自己动，由 Message 带着一起入场。
 */
import { cn } from "cn";
import type * as React from "react";

import { Avatar } from "@/components/ui/avatar";

function MessageGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="message-group"
      className={cn("flex min-w-0 flex-col gap-1.5", className)}
      {...props}
    />
  );
}

/**
 * 消息支持的动效预设（ADR 0021）。缺省 `slide-up`。
 * - `slide-up`：挂载时从下方 16px 升起并淡入，220ms。新到的消息。
 * - `fade`：挂载时只淡入，150ms。一次渲染很多条（加载历史）时。
 * - `none`：直接出现。
 */
type MessageMotion = "none" | "fade" | "slide-up";

function Message({
  className,
  align = "start",
  motion = "slide-up",
  ...props
}: React.ComponentProps<"div"> & { align?: "start" | "end"; motion?: MessageMotion }) {
  return (
    <div
      data-slot="message"
      data-align={align}
      data-motion={motion === "none" ? undefined : motion}
      className={cn(
        "group/message relative flex w-full min-w-0 gap-1.5 text-xs data-[align=end]:flex-row-reverse",
        className,
      )}
      {...props}
    />
  );
}

/** 子元素用原装 Avatar 的 AvatarImage／AvatarFallback。 */
function MessageAvatar({ className, ...props }: React.ComponentProps<typeof Avatar>) {
  return (
    <Avatar
      data-slot="message-avatar"
      className={cn(
        "self-end group-has-data-[slot=message-footer]/message:-translate-y-8",
        className,
      )}
      {...props}
    />
  );
}

function MessageContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="message-content"
      className={cn(
        "flex w-full min-w-0 flex-col gap-2 wrap-break-word group-data-[align=end]/message:*:data-slot:self-end",
        className,
      )}
      {...props}
    />
  );
}

function MessageHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="message-header"
      className={cn(
        "flex max-w-full min-w-0 items-center px-2.5 text-xs font-medium text-muted-foreground group-has-data-[variant=ghost]/message:px-0",
        className,
      )}
      {...props}
    />
  );
}

function MessageFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="message-footer"
      className={cn(
        "flex max-w-full min-w-0 items-center px-2.5 text-xs font-medium text-muted-foreground group-has-data-[variant=ghost]/message:px-0 group-data-[align=end]/message:justify-end",
        className,
      )}
      {...props}
    />
  );
}

export {
  Message,
  MessageAvatar,
  MessageContent,
  MessageFooter,
  MessageGroup,
  MessageHeader,
  type MessageMotion,
};
